{
  "critique": [
    {
      "design": "r2A",
      "good": "The Time column is exactly wide enough for 'Time' and stays a narrow 65px axis. Monday and Tuesday prose columns are equal at 150px, all headers stay on one line, and no words are split.",
      "problems": "At 593px it overflows the 360px box by 233px, and the render shows only the Monday block plus a sliver of Tuesday, so comparing days requires a long horizontal scroll. The 11:00 row is 106px tall and the 09:00/10:00 block is also 106px, making the table 286px tall and visually heavy at the closed notice.",
      "cause": "Both 150px prose columns give only 129px of text width, just below the roughly 144px needed to keep 'accepted until 10:30' and the Tuesday equivalent on one line. Both long cells wrap to four lines, and the four-line Tuesday cell sets the tall 11:00 row."
    },
    {
      "design": "r2B",
      "good": "Widening Tuesday Room B to 172px reduces the long Tuesday prose to three lines and cuts the table height to 262px. The Time column remains compact and there are no mid-word splits.",
      "problems": "The 145/172 split makes the parallel room columns visibly unequal: Monday Room A wraps to four lines while Tuesday Room B wraps to three, so the Monday 09:00/10:00 block is taller than necessary and the table looks left-heavy. Total width grows to 610px, increasing horizontal scroll beyond r2A.",
      "cause": "At 145px, Monday Room A has 124px of text and sits below the three-line threshold, while at 172px Tuesday Room B has 151px and sits above it. The 27px difference is enough to change the line count and produce the imbalance."
    },
    {
      "design": "r2C",
      "good": "Symmetric 175px prose columns give both long cells three lines, produce the shortest table at 239px, keep the Monday and Tuesday blocks balanced, and preserve all words and one-line headers.",
      "problems": "At 643px it is the widest design, overflowing by 283px. The Monday prose breaks as 'Cardiology clinic (Dr.' / 'Ito), walk-ins', separating the title from the clinician's name. The 175px Monday column is also wider than needed once that break is fixed.",
      "cause": "At 175px the text width is 154px, just enough to fit 'Cardiology clinic (Dr.' but not 'Ito),', so the browser breaks after 'Dr.'. Using 175px on both prose columns maximizes total width even though 165px is sufficient for three lines."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "r3-compact",
      "widths": [65, 165, 108, 119, 165],
      "change": "Reduce both prose columns from 175px to 165px, giving 144px of text. This is the threshold where 'Cardiology clinic' / '(Dr. Ito), walk-ins' / 'accepted until 10:30' fits in three lines and the bad break after 'Dr.' disappears. If Tuesday prose also holds at three lines, the table is 622px wide with the same roughly 239px height as r2C; otherwise it trades 10px of width for one extra line."
    },
    {
      "name": "r3-balanced",
      "widths": [65, 165, 108, 119, 175],
      "change": "Keep Tuesday Room B at the proven 175px for three-line prose, but narrow Monday Room A to 165px so the break falls before '(Dr.' and 'Dr. Ito' stays together. Total 632px, 11px narrower than r2C, with both day blocks still fitting inside a 360px viewport when scrolled to."
    },
    {
      "name": "r3-narrow",
      "widths": [65, 145, 108, 119, 145],
      "change": "Trade height for width: 145px prose columns, giving 124px of text, are the narrowest safe point that keeps '(Dr. Ito), walk-ins' on one line. This produces a 582px table, 40px narrower than r3-compact, but the long cells wrap to four lines and the height returns to about 286px. Both day blocks remain under 360px, so horizontal scrolling is reduced without splitting words."
    }
  ]
